          "claim": "Train-food server spans stop on old pod zb6b2 at 11:28:09 and resume on new pod 64vkq from 11:29:19, a gap of about 70 seconds."
        },
        {
          "kind": "log",
          "sql": "SELECT CAST(time AS VARCHAR) t, service_name, attr_k8s_pod_name, substr(message,1,400) msg FROM abnormal_logs WHERE attr_log_template LIKE 'Servlet.service()%' LIMIT 3",
          "claim": "ts-food-service logs 'Connection refused' calling ts-train-food-service trainfoods endpoint during the outage window."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, attr_http_response_status_code sc, count(*) c FROM abnormal_traces WHERE attr_status_code='Error' GROUP BY ALL ORDER BY c DESC",
          "claim": "108 food-service GET client calls to train-food failed with no status code and no child span, matching the outage."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-train-food-service",
      "to": "ts-food-service",
